# Let me build the output grid based on my analysis

def generate_output(rows, cols):
    # Create output grid initialized to 0
    output = [[0 for _ in range(cols)] for _ in range(rows)]

    # Horizontal line at row 6 (only row with non-zero values)
    horizontal = [1, 2, 1, 8, 1, 1, 1, 8, 1, 2, 1]

    # Copy horizontal line to output at row 6
    for c in range(cols):
        output[6][c] = horizontal[c]

    # Determine vertical line columns
    # Rule: columns with value >= 2, and start of cliques of 1s following such columns
    cliques = []
    i = 0
    while i < cols:
        if horizontal[i] == 1:
            start = i
            while i < cols and horizontal[i] == 1:
                i += 1
            cliques.append((start, i-1))
        else:
            i += 1

    vals_ge2 = [i for i, v in enumerate(horizontal) if v >= 2]

    result_cols = set()
    for idx in vals_ge2:
        result_cols.add(idx)
    for start, end in cliques:
        if start > 0 and horizontal[start - 1] >= 2:
            result_cols.add(start)

    result_cols = sorted(result_cols)
    print(f"Vertical line columns: {result_cols}")

    # Determine heights for each column
    # From demo: value 2 -> height 1, value 1 -> height 3, value 8 -> height 3
    # Simplified: height = 1 if horizontal_value == 2, else 3
    vertical_heights = {}
    for c in result_cols:
        h = horizontal[c]
        if h == 2:
            vertical_heights[c] = 1
        else:
            vertical_heights[c] = 3

    # Add vertical lines above horizontal (from row 5 up)
    for c in result_cols:
        height = vertical_heights[c]
        for r in range(5, 5 - height, -1):  # rows 5, 4, 3
            if r >= 0:
                output[r][c] = horizontal[c]
                print(f"Col {c}, row {r}: value {horizontal[c]}")

    return output

